  /* --- model ---------------------------------------------------------------------- */

  var LAYERS = ['E', 'W', 'H', 'D'];
  var NAME = { E: 'Electricity', W: 'Basic water', H: 'Health coverage', D: 'Internet use' };
  var TGT = { E: 95, W: 95, H: 80, D: 90 };
  var WORK = { E: 80, W: 85, H: 65, D: 70 };
  var PROFILES = ['E', 'W', 'H', 'D', 'C'];
  var PNAME = { E: 'Energy-first', W: 'Water-first', H: 'Health-first', D: 'Digital-first', C: 'Consolidating' };

  var C = DATA.c.map(function (r) {
    return { iso: r[0], name: r[1], reg: r[2], inc: r[3], p24: r[4], p50: r[5], s: { E: r[6], W: r[7], H: r[8], D: r[9] }, ws: r[10] };
  });
  var BY = {};

  function latest(c, L) { var s = c.s[L]; for (var i = s.length - 1; i >= 0; i--) if (s[i] !== null) return [2000 + i, s[i]]; return null; }
  function slope(c, L) {
    var y1 = latest(c, L)[0], pts = [];
    c.s[L].forEach(function (v, i) { var y = 2000 + i; if (v !== null && y >= y1 - 9 && y <= y1) pts.push([y, v]); });
    if (pts.length < 5) return 0;
    var mx = 0, my = 0; pts.forEach(function (p) { mx += p[0]; my += p[1]; }); mx /= pts.length; my /= pts.length;
    var sxy = 0, sxx = 0; pts.forEach(function (p) { sxy += (p[0] - mx) * (p[1] - my); sxx += (p[0] - mx) * (p[0] - mx); });
    return sxy / sxx;
  }
  C.forEach(function (c) {
    BY[c.iso] = c; c.now = {}; c.pace = {};
    LAYERS.forEach(function (L) { c.now[L] = latest(c, L); c.pace[L] = slope(c, L); });
    c.prof = c.now.E[1] < WORK.E ? 'E' : c.now.W[1] < WORK.W ? 'W' : c.now.H[1] < WORK.H ? 'H' : c.now.D[1] < WORK.D ? 'D' : 'C';
  });
  function proj(c, L, year, m) { var n = c.now[L]; return Math.min(100, n[1] + Math.max(0, c.pace[L]) * (m || 1) * (year - n[0])); }
  function arrival(c, L, mult, ceil) {
    var n = c.now[L], t = TGT[L];
    if (n[1] >= t) return n[0];
    for (var y = n[0] + 1; y <= 2100; y++) {
      var p = proj(c, L, y, mult[L]);
      if (ceil && L === 'D') p = Math.min(p, proj(c, 'E', y, mult.E) + 5);
      if (p >= t - 1e-9) return y;
    }
    return 9999;
  }
  function run(mult, ceil) {
    var short = { E: 0, W: 0, H: 0, D: 0 }, by = { 2030: { E: 0, W: 0, H: 0, D: 0 }, 2040: { E: 0, W: 0, H: 0, D: 0 }, 2050: short };
    var all = 0, allPop = 0, shortPop = 0;
    C.forEach(function (c) {
      var ok = true;
      LAYERS.forEach(function (L) {
        var a = arrival(c, L, mult, ceil);
        if (a > 2030) by[2030][L]++;
        if (a > 2040) by[2040][L]++;
        if (a > 2050) { short[L]++; ok = false; }
      });
      if (ok) { all++; allPop += c.p50; } else shortPop += c.p50;
    });
    return { short: short, by: by, all: all, allPop: allPop, shortPop: shortPop };
  }
  function median(a) { var s = a.slice().sort(function (x, y) { return x - y; }); var n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; }

