      svg.addEventListener('click', function (e) { var t = e.target.closest('[data-iso]'); var iso = t && t.getAttribute('data-iso'); if (iso && BY[iso]) { picked = iso; showCountry(BY[iso]); paint(); if (onPick) onPick(iso); } });
